insert into public.services (slug, title, icon, description, image_url, inclusions, suitable, activities, is_featured, is_published, sort_order) values
  ('corporate-gathering', 'Corporate Gathering', '◈', 'Bangun koneksi yang lebih kuat di tempat kerja melalui gathering yang dirancang dengan cermat. Kami menyatukan destinasi, akomodasi, hiburan, aktivitas tim, dan koordinasi acara.', 'https://images.unsplash.com/photo-1517457373958-b7bdd4587205?auto=format&fit=crop&w=900&q=82', array['Company gathering & annual gathering','Employee outing dan corporate retreat','Perayaan perusahaan','Program multi-hari','Koordinasi hotel, aktivitas, dan acara']::text[], 'Perusahaan, institusi, HR, General Affairs, dan panitia acara.', 'Sesi kebersamaan, malam apresiasi, aktivitas kelompok, dan acara tematik.', true, true, 10),
  ('team-building', 'Team Building & Outbound', '⌁', 'Program kreatif untuk melatih komunikasi, kolaborasi, pemecahan masalah, dan keterlibatan karyawan sesuai tujuan tim Anda.', 'https://images.unsplash.com/photo-1528605248644-14dd04022da1?auto=format&fit=crop&w=900&q=82', array['Fun games dan team challenges','Aktivitas outdoor maupun indoor','Program leadership','Permainan problem solving','Rangkaian aktivitas yang disesuaikan']::text[], 'Tim kerja, organisasi, komunitas, dan kelompok dengan berbagai ukuran.', 'Ice breaking, relay, tantangan strategi, dan aktivitas kolaboratif.', true, true, 20),
  ('family-gathering', 'Family Gathering', '♡', 'Ciptakan momen berharga untuk karyawan dan keluarga melalui acara yang menyenangkan, inklusif, dan tertata.', 'https://images.unsplash.com/photo-1511895426328-dc8714191300?auto=format&fit=crop&w=900&q=82', array['Pilihan resort dan lokasi','Aktivitas ramah keluarga','Hiburan dan permainan','Koordinasi akomodasi','Dokumentasi acara opsional']::text[], 'Perusahaan, komunitas, dan keluarga besar.', 'Family games, hiburan, aktivitas santai, dan acara kebersamaan.', true, true, 30),
  ('corporate-travel', 'Corporate Travel & Incentive Trip', '✈', 'Apresiasi tim, perkuat relasi, dan wujudkan perjalanan bisnis yang berkesan dengan pengelolaan perjalanan grup yang profesional.', 'https://images.unsplash.com/photo-1488646953014-85cb44e25828?auto=format&fit=crop&w=900&q=82', array['Incentive travel dan reward trip','Perjalanan korporat domestik dan internasional','Pengaturan perjalanan bisnis','Koordinasi grup dan itinerary','Dukungan operasional perjalanan']::text[], 'Perusahaan, tim penjualan, mitra bisnis, dan organisasi.', 'Wisata grup, pengalaman destinasi, agenda kebersamaan, dan perjalanan insentif.', true, true, 40),
  ('private-trip', 'Private Trip & One Day Trip', '⌖', 'Jelajahi destinasi melalui rencana perjalanan personal yang mengikuti preferensi, jadwal, dan anggaran grup Anda.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=82', array['Perjalanan keluarga privat','One day trip dan weekend trip','Paket grup domestik','Perjalanan internasional','Rencana perjalanan fleksibel']::text[], 'Keluarga, komunitas, rombongan privat, dan wisatawan.', 'Wisata alam, pengalaman budaya, rekreasi, dan perjalanan sesuai minat.', true, true, 50),
  ('meeting-event', 'Meeting, Conference & Event', '▤', 'Dari rapat bisnis hingga konferensi dan acara khusus, kami membantu mengelola detail yang mendukung acara berjalan lancar.', 'https://images.unsplash.com/photo-1511578314322-379afb476865?auto=format&fit=crop&w=900&q=82', array['Paket meeting half-day dan full-day','Pilihan ruang rapat dan ballroom hotel','Konferensi dan gala dinner','Hiburan dan produksi acara','Pencarian venue dan koordinasi']::text[], 'Perusahaan, asosiasi, institusi, dan penyelenggara acara.', 'Rapat, konferensi, peluncuran internal, gala dinner, dan acara perusahaan.', true, true, 60),
  ('hotel-accommodation', 'Hotel & Accommodation', '⌂', 'Temukan akomodasi yang sesuai bagi acara atau perjalanan Anda melalui bantuan pencarian hotel dan koordinasi pemesanan.', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=82', array['Pemesanan hotel korporat','Reservasi kamar grup','Paket meeting hotel','Seleksi resort','Bundling akomodasi dengan acara']::text[], 'Perusahaan, panitia acara, dan grup perjalanan.', 'Pencarian opsi penginapan, koordinasi kebutuhan grup, dan pengaturan paket meeting.', false, true, 70),
  ('transportation-logistics', 'Transportation & Logistics', '↗', 'Koordinasikan transportasi dan kebutuhan pendukung untuk membantu peserta menikmati pengalaman yang lebih lancar.', 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=900&q=82', array['Bus, Hiace, dan kendaraan perjalanan','Airport transfer','Transportasi acara','Kendaraan lokal','Koordinasi logistik kegiatan']::text[], 'Penyelenggara gathering, perusahaan, dan grup perjalanan.', 'Rencana penjemputan, mobilitas peserta, dan koordinasi perjalanan acara.', false, true, 80)
