insert into public.products (slug, title, category, description, duration, destination_names, categories, price_amount, price_label, image_url, image_path, inclusions, exclusions, is_featured, is_published, sort_order) values
  ('corporate-gathering-3d2n', 'Corporate Gathering 3D2N', 'Corporate Gathering', 'Perjalanan gathering perusahaan multi-hari dengan akomodasi hotel, aktivitas acara, team building, konsumsi, pengaturan transportasi, dan koordinasi operasional.', '3 hari 2 malam', array['Bogor & Puncak','Sentul','Bandung','Bali','Anyer']::text[], array['Corporate Gathering','','']::text[], null, 'Harga melalui penawaran', 'https://images.unsplash.com/photo-1517457373958-b7bdd4587205?auto=format&fit=crop&w=900&q=82', '', array[]::text[], array[]::text[], true, true, 10),
  ('corporate-gathering-2d1n', 'Corporate Gathering 2D1N', 'Corporate Gathering', 'Program gathering semalam yang menyatukan akomodasi, aktivitas grup, kebersamaan tim, dan pengalaman yang berkesan.', '2 hari 1 malam', array['Bogor & Puncak','Sentul','Bandung','Bali','Anyer']::text[], array['Corporate Gathering','','']::text[], null, 'Harga melalui penawaran', 'https://images.unsplash.com/photo-1528605248644-14dd04022da1?auto=format&fit=crop&w=900&q=82', '', array[]::text[], array[]::text[], true, true, 20),
  ('beach-gathering-team-building', 'Beach Gathering & Team Building', 'Team Building', 'Pengalaman gathering pesisir dengan aktivitas pantai, tantangan tim, permainan, dan hiburan kelompok.', 'Fleksibel', array['Anyer','Pulau Sangiang','Pulau Harapan']::text[], array['Team Building','','']::text[], null, 'Harga melalui penawaran', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=82', '', array[]::text[], array[]::text[], true, true, 30),
  ('mountain-escape-team-building', 'Mountain Escape & Team Building', 'Team Building', 'Pengalaman korporat di alam dengan aktivitas luar ruang, opsi trekking, team building, dan waktu untuk bersantai.', 'Fleksibel', array['Sentul','Bogor & Puncak','Dieng']::text[], array['Team Building','','']::text[], null, 'Harga melalui penawaran', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=900&q=82', '', array[]::text[], array[]::text[], false, true, 40),
  ('one-day-corporate-gathering', 'One Day Corporate Gathering', 'Corporate Gathering', 'Program sehari yang mencakup pengaturan venue, makan siang, coffee break, fun games, dan opsi dokumentasi acara.', '1 hari', array['Bogor & Puncak','Sentul','Bandung','Bali','Anyer']::text[], array['Corporate Gathering','One Day Trip','','']::text[], null, 'Harga melalui penawaran', 'https://images.unsplash.com/photo-1511578314322-379afb476865?auto=format&fit=crop&w=900&q=82', '', array[]::text[], array[]::text[], false, true, 50),
  ('family-gathering-resort-experience', 'Family Gathering Resort Experience', 'Family Gathering', 'Program gathering keluarga dengan akomodasi resort, hiburan, aktivitas keluarga, dan pengalaman bersama.', 'Fleksibel', array['Bogor & Puncak','Sentul','Bandung','Bali','Anyer']::text[], array['Family Gathering','','']::text[], null, 'Harga melalui penawaran', 'https://images.unsplash.com/photo-1517457373958-b7bdd4587205?auto=format&fit=crop&w=900&q=82', '', array[]::text[], array[]::text[], false, true, 60),
  ('domestic-private-trip', 'Domestic Private Trip', 'Private Trip', 'Pengaturan perjalanan privat yang fleksibel untuk keluarga, komunitas, dan grup privat.', 'Fleksibel', array['Anyer','Pulau Sangiang','Pulau Harapan','Sentul','Bogor & Puncak','Bandung','Yogyakarta','Dieng','Garut','Bali','Lampung','Belitung','Karimunjawa']::text[], array['Private Trip','Domestic Tour','']::text[], null, 'Harga melalui penawaran', 'https://images.unsplash.com/photo-1528605248644-14dd04022da1?auto=format&fit=crop&w=900&q=82', '', array[]::text[], array[]::text[], false, true, 70),
  ('international-incentive-trip', 'International Incentive Trip', 'International Tour', 'Program perjalanan grup internasional yang dikoordinasikan untuk apresiasi korporat dan pengalaman organisasi.', 'Fleksibel', array['Malaysia','Singapore','Vietnam','Thailand']::text[], array['International Tour','','International Tour']::text[], null, 'Harga melalui penawaran', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=82', '', array[]::text[], array[]::text[], false, true, 80),
  ('corporate-meeting-package', 'Corporate Meeting Package', 'Meeting Package', 'Pengaturan meeting yang mencakup opsi ruang hotel, coffee break, makan siang, akomodasi, serta kebutuhan acara pendukung.', 'Half-day / full-day', array['Bogor & Puncak','Sentul','Bandung','Bali','Anyer']::text[], array['Meeting Package','','']::text[], null, 'Harga melalui penawaran', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=900&q=82', '', array[]::text[], array[]::text[], false, true, 90),
  ('customized-corporate-event', 'Customized Corporate Event', 'Meeting Package', 'Solusi manajemen acara yang dirancang berdasarkan tujuan perusahaan, peserta, destinasi pilihan, dan anggaran.', 'Sesuai program', array['Bogor & Puncak','Sentul','Bandung','Bali','Anyer']::text[], array['Meeting Package','','']::text[], null, 'Harga melalui penawaran', 'https://images.unsplash.com/photo-1511578314322-379afb476865?auto=format&fit=crop&w=900&q=82', '', array[]::text[], array[]::text[], false, true, 100)
